/* Consulta de encontros e piloto de histórico pastoral. */
const recordField=(label,value)=>`<div class="record-field"><h3>${label}</h3><p>${esc(value||'Não informado')}</p></div>`;
function recordDialog(title,sub,body){openDlg(`${dlgHead(title,sub)}<div class="record-body">${body}</div><div class="dfoot"><button class="btn sec" data-a="closeDlg">Fechar</button></div>`);}
function dViewMeet(id){const d=dById(S.disc),m=d.meets.find(x=>x.id===id);if(!m)return;recordDialog('Encontro realizado',`${esc(d.n)} · ${fmtD(m.d)} · ${m.time}`,recordField('Conteúdo tratado',m.content)+recordField('Participantes',(m.parts||partsOf(d)).join(', '))+recordField('Material de apoio',m.mat)+recordField('Anotação pessoal · só você vê',m.note));}
function hViewMeet(id){const c=hById(S.casa),m=c.meets.find(x=>x.id===id);if(!m)return;recordDialog('Encontro realizado',`${esc(c.n)} · ${fmtD(m.d)}`,recordField('O que foi tratado',m.desc)+recordField('Material de apoio',m.mat)+`<h3>Chamada</h3><div class="record-attendance">${c.ppl.map(p=>`<div><span>${esc(p.n)}${!m.pres[p.id]&&m.why[p.id]?`<small>${esc(m.why[p.id])}</small>`:''}</span><b>${m.pres[p.id]?'Presente':'Ausente'}</b></div>`).join('')}</div><h3>Registros do encontro</h3><ol class="mini-tl">${(m.entries||[{d:m.d,t:'Encontro realizado e chamada registrada',by:c.leader}]).map(e=>`<li><b>${esc(e.t)}</b><span>${fmtD(e.d)} · ${esc(e.by)}</span></li>`).join('')}</ol><button class="btn sec" data-a="hEditMeet" data-v="${m.id}">Editar registro e chamada</button>`);}
let careSequence=0;
function careInit(c){if(c.events)return;c.cancelled=c.cancelled||[];c.events=[{d:c.opened,title:'Caso aberto',text:c.type,by:c.resp}];for(const [kind,items] of [['done',c.meets],['sched',c.sched||[]]])for(const m of items){m.rid=m.rid||'care'+(++careSequence);c.events.push({d:kind==='sched'?c.opened:m.d,title:kind==='done'?'Encontro realizado':'Encontro agendado',text:kind==='done'?m.t:`${fmtD(m.d)} · ${m.t}`,by:c.resp,ref:m.rid});}if(c.resolved)c.events.push({d:c.resolved,title:'Caso resolvido',text:'Acompanhamento encerrado',by:c.resp});}
function careLog(c,title,text,ref){careInit(c);c.events.push({d:new Date().toISOString(),title,text,by:ME.n||'Usuário atual',ref});}
function careTimeline(c){careInit(c);return `<section class="card pc care-history"><div class="sh"><h2>Histórico do acompanhamento</h2><span class="who">${c.events.length} registros</span></div><p class="who">A trajetória deste caso, com a mesma visibilidade do acompanhamento.</p><ol class="htl">${c.events.slice().sort((a,b)=>b.d.localeCompare(a.d)).map(e=>`<li><span class="hd2">${fmtD(e.d.slice(0,10))}${e.d.includes('T')?`<small>${new Date(e.d).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small>`:''}</span><span class="hdot"></span><span class="hb"><b>${esc(e.title)}</b><span>${esc(e.text)} · por ${esc(e.by)}</span>${e.ref?`<button class="lnk" data-a="careMeet" data-v="${e.ref}">Ver encontro ${ic('arrowR',13)}</button>`:''}</span></li>`).join('')}</ol></section>`;}
function careMeet(id){const c=cById(S.case);careInit(c);const m=[...c.meets,...c.sched,...c.cancelled].find(x=>x.rid===id);if(!m)return;const done=c.meets.includes(m),cancel=c.cancelled.includes(m);recordDialog(cancel?'Encontro cancelado':done?'Encontro realizado':'Encontro agendado',`${esc(c.n)} · ${fmtD(m.d)}`,recordField('Situação',cancel?'Cancelado':done?'Realizado':'Agendado')+recordField('Conteúdo tratado',done?m.t:'Ainda não realizado')+recordField('Resultado / próximos passos',m.result)+recordField('Modalidade',m.mode)+recordField('Horário',done?m.time:m.t)+recordField('Local',m.where));}
function careMeetings(c){careInit(c);return `<section class="card pc"><div class="sh"><h2>Encontros</h2><button class="btn sec sm" data-a="cReg" data-v="${c.id}">Registrar encontro</button></div>${[['Agendados',c.sched,'sched'],['Realizados',c.meets,'done'],['Cancelados',c.cancelled,'cancel']].map(([label,items,kind])=>`<h3>${label} <small class="who">${items.length}</small></h3>${items.length?items.map((m,i)=>`<div class="care-meeting"><button class="care-meeting-open" data-a="careMeet" data-v="${m.rid}"><b>${kind==='done'?esc(m.t):'Encontro '+esc(m.mode||'pastoral').toLowerCase()}</b><span>${fmtD(m.d)}${kind!=='done'?' · '+esc(m.t):''}</span>${kind==='done'?`<span>Resultado: ${esc(m.result||'Não informado')}</span>`:''}</button>${kind==='sched'?`<div class="row2"><button class="btn sec sm" data-a="cDone" data-v="${c.id}|${i}">Concluir</button><button class="ibtn" data-a="cUnsched" data-v="${c.id}|${i}" aria-label="Cancelar encontro">${ic('x',14)}</button></div>`:''}</div>`).join(''):'<p class="who">Nenhum encontro nesta situação.</p>'}`).join('')}</section>`;}
const careOldDetail=caseDetail;
caseDetail=function(){const c=cById(S.case);if(!c)return careOldDetail();careInit(c);const original=careOldDetail(),end=original.indexOf('</header>'),start=original.indexOf('<aside class="stack-col">'),finish=original.indexOf('</aside>',start);const tab=S.careTab||'details';return original.slice(0,end)+`<div class="ptabs" role="tablist">${[['details','Detalhes'],['meetings','Encontros'],['history','Histórico']].map(([id,t])=>`<button role="tab" aria-selected="${tab===id}" class="${tab===id?'on':''}" data-a="careTab" data-v="${id}">${t}</button>`).join('')}<span class="tind"></span></div></header><div class="rise">${tab==='history'?careTimeline(c):tab==='meetings'?careMeetings(c):`<div class="care-details">${original.slice(start+'<aside class="stack-col">'.length,finish)}</div>`}</div>`;};
const careOldAfter=caseAfter;
caseAfter=function(){requestAnimationFrame(tabInd);const c=cById(S.case);if(c)careInit(c);const group=$('#cstG');if(group)group.addEventListener('change',e=>{const old=c.st,next=e.target.value;if(old!==next)careLog(c,'Situação alterada',`${CST[old][0]} → ${CST[next][0]}`);});careOldAfter();};
const CAREA={dViewMeet,hViewMeet,hEditMeet:id=>{closeDlg();HA.hCall(id);},careMeet,careTab:v=>{S.careTab=v;render();},mnInspect:v=>{const [kind,index]=v.split('|'),m=mnById(S.mini),i=+index;if(kind==='team'){const t=m.teams[i];recordDialog(t.n,'Time · '+esc(m.n),recordField('Líder',t.lead)+recordField('Participantes',String(t.m)));}else if(kind==='resp')recordDialog('Responsabilidade',esc(m.n),recordField('Descrição',m.resp[i]));else {const c=m.content[i];recordDialog(c[1],'Conteúdo vinculado · '+esc(m.n),recordField('Tipo',c[0])+recordField('Título',c[1]));}}};

/* Identity: demonstration of users, roles and scoped access. No authorization engine. */
const ID_ROLE_SCOPE=Object.fromEntries(Object.keys(ROLES).map(r=>[r,'Igreja']));
ROLES['Administrador da organização']=['st-rec'];RPERM['Administrador da organização']=rp(Object.fromEntries(MODS.map(m=>[m,ACTS])));ID_ROLE_SCOPE['Administrador da organização']='Organização';
const idProtected=r=>r==='Administrador'||r==='Administrador da organização';
const ID_HISTORY={};
const idChurch=()=>CHURCHES[S.church||0];
const idChurchId=()=>IGREJAS.find(g=>g.n.startsWith(idChurch().n))?.id||'g1';
const idStatus=u=>u.revoked?'Revogado':!u.active?'Suspenso':u.last==='convite enviado'?'Convidado':'Ativo';
const idLast=u=>u.LastLoginAt?new Date(u.LastLoginAt).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'Nunca acessou';
USERS.forEach((u,i)=>{u.LastLoginAt=u.last==='convite enviado'?null:`2026-09-${String(30-i).padStart(2,'0')}T09:30:00`;});
USERS[3].active=false;SCOPES.push(SC('Integração',USERS[0].n,'Admin'));SCOPES.push(SC('Ministério de Louvor',USERS[1].n,'Editar'));
const idHistoryFor=n=>ID_HISTORY[n]||(ID_HISTORY[n]=[{at:'2026-09-01T09:00:00',title:'Acesso administrativo registrado',detail:'Cadastro inicial da demonstração',actor:'Administração'}]);
function idRecord(n,title,detail){idHistoryFor(n).push({at:new Date().toISOString(),title,detail,actor:'Rafael Pereira'});}
function idTimeline(n){return `<section class="card pc id-history"><div class="sh"><h2>Histórico</h2></div><ol class="htl">${idHistoryFor(n).slice().reverse().map(e=>`<li><span class="hd2">${new Date(e.at).toLocaleDateString('pt-BR')}<small>${new Date(e.at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></span><span class="hdot"></span><span class="hb"><b>${esc(e.title)}</b><span>${esc(e.detail)}</span><span>Por ${esc(e.actor)}</span></span></li>`).join('')}</ol></section>`;}
function idUserAreaRows(u){return SCOPES.filter(x=>x.who===u.n);}
function idUserAreas(u){return idUserAreaRows(u).length?scopeTab(u):'<section class="card pc"><h2>Áreas</h2><p class="who">Este usuário não possui acessos específicos por área.</p></section>';}
function idStatusPill(u){const st=idStatus(u),t=st==='Ativo'?'st-int':st==='Convidado'?'st-sol':'st-rec';return `<span class="stp" style="--c:var(--${t});--b:var(--${t}-bg)"><i></i>${st}</span>`;}
usersTab=function(){const q=norm(S.uq||''),list=USERS.filter(u=>!u.revoked&&(S.idListScope==='org'||u.cur===idChurchId())&&(!q||norm(u.n+' '+u.e+' '+u.role).includes(q))&&(!S.idStatusFilter||idStatus(u)===S.idStatusFilter));return `<section class="card mtab"><div class="tbar"><label class="sbox">${ic('search',16)}<input id="uq" placeholder="Buscar por nome, e-mail ou papel" value="${esc(S.uq||'')}"></label><div class="segc">${[['church','Desta igreja'],['org','Da organização']].map(([k,t])=>`<button data-a="idListScope" data-v="${k}" aria-pressed="${(S.idListScope||'church')===k}">${t}</button>`).join('')}</div></div><div class="chips" style="padding:0 20px 16px">${['','Ativo','Convidado','Suspenso'].map(t=>`<button class="chipf ${(S.idStatusFilter||'')===t?'on':''}" data-a="idStatusFilter" data-v="${t}">${t||'Todos'}</button>`).join('')}</div><div class="id-table-scroll"><table class="id-table"><thead><tr><th>Usuário</th><th>Papel</th><th>Situação</th><th>Último acesso</th><th></th></tr></thead><tbody>${list.map(u=>`<tr><td><button class="dk" data-a="uOpen" data-v="${u.id}">${uAv(u)}<span class="dkt"><b>${esc(u.n)}</b><span>${esc(u.e)}</span></span></button></td><td>${rPill(u.role)}</td><td>${idStatusPill(u)}</td><td>${idLast(u)}</td><td><button class="ibtn" data-a="uOpen" data-v="${u.id}" aria-label="Abrir ${esc(u.n)}">${ic('chevR',16)}</button></td></tr>`).join('')}</tbody></table></div>${list.length?'':'<div class="mempty"><p>Nenhum usuário corresponde aos filtros.</p></div>'}<div class="tfoot">${list.length} usuários</div></section>`;};
userDetail=function(){const u=uById(S.user);if(!u)return usersList();const tab=S.idUserTab||'overview',scopes=idUserAreaRows(u);return `<nav class="crumb"><button class="lnk" data-a="uBack">Usuários e permissões</button>${ic('chevR',14)}${esc(u.n)}</nav><header class="card prof rise"><div class="pid">${uAv(u,'xl')}<div class="pn"><h1>${esc(u.n)}</h1><p>${esc(u.e)} · ${esc(u.role)}</p></div></div><div class="pact">${idStatusPill(u)}<button class="btn sec" data-a="uReset">${ic('key',15)}Redefinir senha</button><div style="position:relative"><button class="ibtn" data-a="uMenu" aria-label="Mais ações">${ic('dots',18)}</button><div class="pop" id="uPop" style="right:0;top:calc(100% + 6px)"><button class="pi" data-a="uRole">${ic('shield',17)}Alterar papel</button><button class="pi" data-a="uChurch">${ic('church',17)}Trocar igreja</button><button class="pi" data-a="uSusp">${ic(u.active?'pause':'check',17)}${u.active?'Suspender acesso':'Reativar acesso'}</button>${u.last==='convite enviado'?`<button class="pi" data-a="uResendInvite">${ic('mail',17)}Reenviar convite</button>`:''}<hr><button class="pi danger" data-a="uDel">${ic('x',17)}Revogar acesso</button></div></div></div><div class="ptabs">${[['overview','Visão geral'],['areas','Áreas'],['history','Histórico']].map(([k,t])=>`<button class="${tab===k?'on':''}" data-a="idUserTab" data-v="${k}">${t}</button>`).join('')}</div></header>${tab==='history'?idTimeline(u.n):tab==='areas'?idUserAreas(u):`<div class="pgrid"><div class="col"><section class="card pc"><div class="sh"><h2>Dados do usuário</h2></div><dl class="kv"><div><dt>E-mail</dt><dd>${esc(u.e)}</dd></div><div><dt>Último acesso</dt><dd>${idLast(u)}</dd></div><div><dt>Papel</dt><dd>${esc(u.role)} · ${ID_ROLE_SCOPE[u.role]||'Igreja'}</dd></div></dl></section><section class="card pc"><div class="sh"><h2>Permissões do papel</h2></div>${MODS.map(m=>`<div class="id-area-row"><span>${m}</span><span class="who">${(RPERM[u.role]?.[m]||[]).join(' · ')||'Sem acesso'}</span></div>`).join('')}</section></div><div class="col"><section class="card pc"><div class="sh"><h2>Igreja de vínculo</h2><button class="btn sec sm" data-a="uChurch">Trocar igreja</button></div><p>${esc(gById(u.cur)?.n||'Igreja')}</p><p class="who">Igreja à qual a pessoa pertence.</p></section><section class="card pc"><div class="sh"><h2>Atividade recente · 30 dias</h2><button class="lnk" data-a="nav" data-v="auditoria">Auditoria ${ic('arrowR',14)}</button></div>${LOG.filter(x=>x.u===u.n&&x.d>='2026-09-01').map(x=>`<div class="id-area-row"><span>${esc(x.a+' '+x.e+' · '+x.x)}<small class="who">${dBRs(x.d)} · ${x.t}</small></span></div>`).join('')||'<p class="who">Nenhuma atividade neste período.</p>'}</section></div></div>`}`;};
function idRoleForm(mode){const current=S.mxRole,rename=mode==='rename';if(rename&&idProtected(current))return;openDlg(`${dlgHead(rename?'Renomear papel':'Novo papel','O alcance é definido na criação e não muda depois.')}<form id="idRoleF" class="fgrid one"><label class="fld"><span class="fl">Nome</span><input name="title" required value="${rename?esc(current):''}" placeholder="Ex.: Tesoureiro"></label><label class="fld"><span class="fl">Alcance</span><select name="scope" ${rename?'disabled':''}><option ${ID_ROLE_SCOPE[current]==='Igreja'?'selected':''}>Igreja</option><option ${rename&&ID_ROLE_SCOPE[current]==='Organização'?'selected':''}>Organização</option></select></label><div class="dfoot"><button class="btn sec" type="button" data-a="closeDlg">Cancelar</button><button class="btn pri" type="submit">Salvar</button></div></form>`,'sm');$('#idRoleF').onsubmit=e=>{e.preventDefault();const f=e.target,n=f.elements.title.value.trim();if(!n)return;if(ROLES[n]&&(!rename||n!==current)){toast('Já existe um papel com esse nome');return;}if(rename&&n!==current){ROLES[n]=ROLES[current];RPERM[n]=RPERM[current];ID_ROLE_SCOPE[n]=ID_ROLE_SCOPE[current];USERS.filter(u=>u.role===current).forEach(u=>{u.role=n;idRecord(u.n,'Papel renomeado',current+' → '+n);});delete ROLES[current];delete RPERM[current];delete ID_ROLE_SCOPE[current];}else if(!rename){ROLES[n]=['st-sol'];RPERM[n]=rp({});ID_ROLE_SCOPE[n]=f.elements.scope.value;}S.mxRole=n;S.mxDraft=null;closeDlg();admRe();toast('Papel salvo');};}
function idDeleteRole(){const role=S.mxRole;if(idProtected(role))return;const users=USERS.filter(u=>!u.revoked&&u.role===role),options=Object.keys(ROLES).filter(r=>r!==role&&ID_ROLE_SCOPE[r]===ID_ROLE_SCOPE[role]);openDlg(`${dlgHead('Excluir papel',role)}<form id="idDeleteRoleF" class="fgrid one"><p class="who">${users.length?'Reatribua os usuários antes de excluir este papel.':'Nenhum usuário vinculado.'}</p>${users.map(u=>`<label class="fld"><span class="fl">${esc(u.n)}</span><select name="${u.id}" required><option value="">Escolha o novo papel</option>${options.map(r=>`<option>${esc(r)}</option>`).join('')}</select></label>`).join('')}<div class="dfoot"><button class="btn sec" type="button" data-a="closeDlg">Cancelar</button><button class="btn pri" type="submit">${users.length?'Reatribuir e excluir':'Excluir papel'}</button></div></form>`);$('#idDeleteRoleF').onsubmit=e=>{e.preventDefault();for(const u of users){const next=e.target.elements[u.id].value;if(!next)return;u.role=next;idRecord(u.n,'Papel reatribuído',role+' → '+next);}delete ROLES[role];delete RPERM[role];delete ID_ROLE_SCOPE[role];S.mxRole='Administrador';S.mxDraft=null;closeDlg();admRe();toast('Papel excluído');};}
const idMatrixOriginal=matrixTab;
matrixTab=function(){const r=S.mxRole;return `<div class="id-role-tools"><span class="who">Alcance: <b>${ID_ROLE_SCOPE[r]||'Igreja'}</b> · ${idProtected(r)?'Papel protegido':'Papel de demonstração'}</span>${idProtected(r)?'':`<div class="row2"><button class="btn sec sm" data-a="idRoleRename">Renomear</button><button class="btn sec sm" data-a="idRoleDelete">Excluir papel</button></div>`}</div>`+idMatrixOriginal();};
function idChangeChurch(){closePops();const member=S.idMoveMember?byId(S.idMoveMember):null,linked=member?USERS.find(x=>x.memberId===member.id||member.e&&x.e===member.e):null,u=member?(linked||{n:member.n,cur:member.churchId||idChurchId(),role:'Membro comum'}):uById(S.user);openDlg(`${dlgHead('Trocar igreja',`Mudar o vínculo de ${esc(u.n)}. Não é uma troca de contexto.`)}<form id="idChurchF" class="fgrid one"><label class="fld"><span class="fl">Nova igreja</span><select name="church" required><option value="">Selecione</option>${IGREJAS.filter(g=>g.id!==u.cur).map(g=>`<option value="${g.id}">${esc(g.n)}</option>`).join('')}</select></label><label class="fld"><span class="fl">Papel no destino</span><select name="role"><option value="keep">Manter ${esc(u.role)}</option>${Object.keys(ROLES).filter(r=>ID_ROLE_SCOPE[r]==='Igreja'&&r!==u.role).map(r=>`<option>${esc(r)}</option>`).join('')}<option value="member">Voltar a membro comum</option></select></label><section class="card pc" id="idChurchPreview"></section><div class="dfoot"><button class="btn sec" type="button" data-a="closeDlg">Cancelar</button><button class="btn pri" type="submit" disabled>Confirmar mudança</button></div></form>`);const f=$('#idChurchF'),preview=()=>{const areas=idUserAreaRows(u);$('#idChurchPreview').innerHTML=`<h3>Prévia da mudança</h3><p>${esc(gById(u.cur)?.n||'')} → ${esc(gById(f.elements.church.value)?.n||'Selecione o destino')}</p><p class="who">${areas.length?`Serão encerrados ${areas.length} acessos por área: ${areas.map(x=>esc(x.area)).join(', ')}.`:'Não há acessos por área a encerrar.'}</p><p class="who">${f.elements.role.value==='member'?'O acesso administrativo será encerrado. Cadastro, conta e app permanecem.':`Papel no destino: ${esc(f.elements.role.value==='keep'?u.role:f.elements.role.value)}. O vínculo com a igreja anterior será substituído.`}</p>`;f.querySelector('[type=submit]').disabled=!f.elements.church.value;};f.onchange=preview;preview();f.onsubmit=e=>{e.preventDefault();const from=u.cur,to=f.elements.church.value,r=f.elements.role.value;if(!to)return;for(let i=SCOPES.length-1;i>=0;i--)if(SCOPES[i].who===u.n){idRecord(u.n,'Acesso por área encerrado',SCOPES[i].area+' · mudança de igreja');SCOPES.splice(i,1);}u.cur=to;u.igs=[to];if(r==='member'){u.revoked=true;u.active=false;}else if(r!=='keep')u.role=r;idRecord(u.n,'Igreja de vínculo alterada',gById(from).n+' → '+gById(to).n+' · '+(r==='member'?'Membro comum':u.role));if(member)member.churchId=to;closeDlg();S.idMoveMember=null;S.idUserTab='history';admRe();toast('Vínculo atualizado');};}
function idChangeRole(){closePops();const u=uById(S.user);openDlg(`${dlgHead('Alterar papel',u.n)}<form id="idUserRoleF" class="fgrid one"><label class="fld"><span class="fl">Papel</span><select name="role">${Object.keys(ROLES).filter(r=>ID_ROLE_SCOPE[r]==='Igreja'||r===u.role).map(r=>`<option ${r===u.role?'selected':''}>${esc(r)}</option>`).join('')}</select></label><div class="dfoot"><button type="button" class="btn sec" data-a="closeDlg">Cancelar</button><button type="submit" class="btn pri">Salvar papel</button></div></form>`,'sm');$('#idUserRoleF').onsubmit=e=>{e.preventDefault();const old=u.role;u.role=e.target.elements.role.value;if(old!==u.role)idRecord(u.n,'Papel alterado',old+' → '+u.role);closeDlg();admRe();toast('Papel atualizado');};}
