function idWebCode(title,description,done){openDlg(`${dlgHead(title,description)}<form id="pfCodeF" class="fgrid one"><label class="fld"><span class="fl">Código recebido por e-mail</span><input name="code" inputmode="numeric" maxlength="6" required placeholder="123456"></label><p class="who">Demonstração: use 123456.</p><div class="dfoot"><button class="btn sec" type="button" data-a="closeDlg">Cancelar</button><button class="btn pri" type="submit">Confirmar</button></div></form>`,'sm');$('#pfCodeF').onsubmit=e=>{e.preventDefault();if(e.target.elements.code.value!=='123456'){toast('Use o código de demonstração 123456');return;}closeDlg();done();};}
Object.assign(ID_ACTIONS,{
 pfIdentityEmail:()=>{openDlg(`${dlgHead('Alterar e-mail','Confirme a senha atual e informe o novo endereço.')}<form id="pfEmailF" class="fgrid one"><label class="fld"><span class="fl">Senha atual</span><input name="password" type="password" required autocomplete="current-password"></label><label class="fld"><span class="fl">Novo e-mail</span><input name="email" type="email" required></label><div class="dfoot"><button class="btn sec" type="button" data-a="closeDlg">Cancelar</button><button class="btn pri" type="submit">Enviar código</button></div></form>`,'sm');$('#pfEmailF').onsubmit=e=>{e.preventDefault();const email=e.target.elements.email.value;idWebCode('Confirmar novo e-mail','Código enviado para '+email,()=>{ME.email=email;admRe();toast('E-mail atualizado · demonstração');});};},
 pfIdentityDownload:()=>{openDlg(`${dlgHead('Baixar meus dados','Arquivo de demonstração, sem dados reais.')}<p class="who">Arquivo pronto para baixar.</p><div class="dfoot"><button class="btn pri" data-a="pfIdentityFile">Baixar arquivo</button></div>`,'sm');},
 pfIdentityFile:()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({demonstracao:true,nome:ME.n,email:ME.email},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='alva-dados-demonstracao.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Arquivo demonstrativo baixado');},
 pfIdentityDelete:()=>openDlg(`${dlgHead('Excluir minha conta','A exclusão não pode ser desfeita. Baixe seus dados antes de continuar.')}<p class="who">Permanecem o nome, os registros de retenção obrigatória e a auditoria.</p><button class="btn sec" data-a="pfIdentityFile">${ic('download',15)}Baixar meus dados</button><div class="dfoot"><button class="btn sec" data-a="closeDlg">Manter conta</button><button class="btn dang" data-a="pfIdentityDeleteCode">Enviar código</button></div>`,'sm'),
 pfIdentityDeleteCode:()=>idWebCode('Confirmar exclusão','Código enviado para '+ME.email,()=>openDlg(`${dlgHead('Exclusão concluída','Fim da demonstração. Nenhuma conta real foi excluída.')}<button class="btn pri" data-a="closeDlg">Fechar</button>`,'sm'))
});
document.addEventListener('submit',e=>{if(e.target.id!=='pfIdentityF')return;e.preventDefault();const f=e.target.elements;ME.first=f.first.value.trim();ME.n=ME.first+' '+f.surname.value.trim();ME.tel=f.tel.value;ME.nasc=f.nasc.value;admRe();toast('Dados salvos');});
document.addEventListener('change',e=>{if(e.target.id==='pfLang'){ME.lang=e.target.value;toast('Preferência de idioma salva · demonstração');}});

/* October prototype additions: local UX fixtures. */
const nxOperation=NAV.find(g=>g[0]==='Operação')[1];nxOperation.push(nxOperation.splice(nxOperation.findIndex(i=>i[0]==='shop'),1)[0]);
I.bag='<path d="M5 7h14l1 14H4L5 7Z"/><path d="M9 7V5a3 3 0 0 1 6 0v2"/>';
const NX_VIDEOS=[{id:'vd1',t:'Servir com propósito',desc:'Um convite para servir na comunidade.',url:'https://www.youtube.com/watch?v=jfKfPfyJRdk',tag:'Vida em comunidade',min:'',visibility:'Público',active:true,files:['Guia de reflexão.pdf']},{id:'vd2',t:'Primeiros passos na Alva',desc:'Conheça nossa comunidade e sua caminhada.',url:'https://www.youtube.com/watch?v=5qap5aO4i9A',tag:'Formação',min:'',visibility:'Interno',active:true,files:[]},{id:'vd3',t:'Preparação do time de louvor',desc:'Orientações para o próximo encontro.',url:'https://www.youtube.com/watch?v=jfKfPfyJRdk',tag:'Ministério',min:'Louvor',visibility:'Restrito',active:true,files:[]}];
const NX_SERIES=PSERIES.map(s=>({id:s.id,n:s.n,type:'Pregação',desc:'Uma sequência de mensagens para sua caminhada.',min:'',visibility:'Interno',items:PREGS.filter(p=>p.sr===s.id).map(p=>p.id),people:[{n:'Ana Lima',done:1},{n:'Rafael Pereira',done:99}]}));
NX_SERIES.push({id:'sv1',n:'Vida em comunidade',type:'Vídeo',desc:'Conheça, participe e sirva.',visibility:'Público',min:'',items:['vd1','vd2'],people:[{n:'Ana Lima',done:1},{n:'Rafael Pereira',done:2}]},{id:'sm1',n:'Canções de adoração',type:'Música',desc:'Uma seleção para ouvir e compartilhar.',visibility:'Interno',min:'',items:SONGS.slice(0,3).map(s=>s.id),people:[]});
const nxParentVis=()=>null;/* a série e a jornada filtram o que a pessoa vê; o item e o curso mantêm a visibilidade própria (várias séries e várias jornadas) */
const nxVisOwn=o=>(o.min||CSOLO.find(j=>j.courses.includes(o))?.min)?'Restrito':o.visibility||'Interno';
const nxVis=o=>{const p=nxParentVis(o);return p?nxVisOwn(p.obj):nxVisOwn(o);};
const nxBadge=o=>`<span class="pill nx-vis">${nxVis(o)}</span>`;
const nxFields=o=>{const inh=nxParentVis(o);if(inh)return `<div class="fld wide nx-publication-title"><span class="fl">Publicação no app</span><span class="hint">Defina quem pode acessar este conteúdo.</span></div><label class="fld nx-publication-field"><span class="fl">Visibilidade</span><span class="selw"><select name="nxVisibility" disabled><option>${nxVis(o)}</option></select>${ic('updown',14)}</span></label><input type="hidden" name="nxMin" value=""><p class="hint wide nx-publication-help">Herdada ${inh.kind==='série'?'da série':'da jornada'} “${esc(inh.name)}”. Para mudar, altere ${inh.kind==='série'?'a série':'a jornada'}.</p>`;const parent=[...JORNS,...CSOLO].find(j=>j.courses.includes(o)),min=o.min||parent?.min||'';return `<div class="fld wide nx-publication-title"><span class="fl">Publicação no app</span><span class="hint">Defina quem pode acessar este conteúdo.</span></div><label class="fld nx-publication-field"><span class="fl">Ministério <small>opcional</small></span><span class="selw"><select name="nxMin"><option value="">Sem vínculo</option>${MINIS.filter(m=>m.active).map(m=>`<option ${min===m.n?'selected':''}>${esc(m.n)}</option>`).join('')}</select>${ic('updown',14)}</span></label><label class="fld nx-publication-field"><span class="fl">Visibilidade</span><span class="selw"><select name="nxVisibility" ${min?'disabled':''}>${(min?['Restrito']:['Interno','Público']).map(v=>`<option ${nxVis(o)===v?'selected':''}>${v}</option>`).join('')}</select>${ic('updown',14)}</span></label><p class="hint wide nx-publication-help">${min?'Restrito aos integrantes do ministério selecionado.':nxVis(o)==='Público'?'Público: disponível para todos, inclusive visitantes.':'Interno: disponível apenas para membros logados.'}</p>`;};
function nxBindVis(f,o){const m=f.elements.nxMin,v=f.elements.nxVisibility,help=f.querySelector('.nx-publication-help');const describe=()=>{if(help)help.textContent=m.value?'Restrito aos integrantes do ministério selecionado.':v.value==='Público'?'Público: disponível para todos, inclusive visitantes.':'Interno: disponível apenas para membros logados.';};m.onchange=()=>{const previous=v.value;v.disabled=!!m.value;v.innerHTML=(m.value?['Restrito']:['Interno','Público']).map(t=>`<option ${t===previous?'selected':''}>${t}</option>`).join('');describe();};v.addEventListener('change',describe);}
function nxSaveVisibility(o,f){if(nxParentVis(o))return;o.min=f.elements.nxMin.value;o.visibility=f.elements.nxVisibility.value;const parent=CSOLO.find(j=>j.courses.includes(o));if(parent)parent.min=o.min;}
const nxCatalog=type=>type==='Vídeo'?NX_VIDEOS.map(v=>({id:v.id,t:v.t})):type==='Música'?SONGS.map(v=>({id:v.id,t:v.n})):PREGS.map(v=>({id:v.id,t:v.t}));
const nxThumb=v=>{let id='';try{const u=new URL(v.url);if(u.hostname==='youtu.be')id=u.pathname.slice(1);else if(/(^|\.)youtube\.com$/.test(u.hostname))id=u.searchParams.get('v')||u.pathname.split('/').pop();}catch{}return `<div class="ct-th" style="background:${thumbBg(2)}">${id&&/^[\w-]+$/.test(id)?`<img src="https://i.ytimg.com/vi/${id}/hqdefault.jpg" alt="" style="width:100%;height:100%;object-fit:cover">`:''}<i class="ct-play">${ic('play',20)}</i></div>`;};
function nxVideoList(){
 const series=NX_SERIES.filter(s=>s.type==='Vídeo'),seriesOf=v=>{const l=series.filter(s=>s.items.includes(v.id));return l.length?{id:l[0].id,n:l.map(s=>s.n).join(', ')}:undefined;},q=norm(S.nxVq||''),filter=S.nxVf||'todas';
 const list=NX_VIDEOS.filter(v=>(filter==='todas'||(filter==='serie'?seriesOf(v):!seriesOf(v)))&&(!S.nxVSr||series.some(s=>s.id===S.nxVSr&&s.items.includes(v.id)))&&(!q||norm(v.t+' '+v.desc+' '+v.tag+' '+(seriesOf(v)?.n||'')).includes(q)));
 return `<header class="ph rise"><div><p class="eb">Conteúdo</p><h1>Vídeos</h1><p class="lede">Conteúdos para conhecer, aprender e compartilhar</p></div><div class="pact">${rpBtn('conteudo','videos')}<button class="btn pri" data-a="nxVideoEdit">${ic('plus',15,2.2)}Novo vídeo</button></div></header>
 <section class="card kpis4 rise" style="--d:1"><div class="k4"><span class="kl">Vídeos</span><span class="kv">${NX_VIDEOS.length}</span><span class="kd">na biblioteca</span></div><div class="k4"><span class="kl">Vídeos ativos</span><span class="kv">${NX_VIDEOS.filter(v=>v.active).length}</span><span class="kd">${NX_VIDEOS.filter(v=>!v.active).length} inativos</span></div><div class="k4"><span class="kl">Séries</span><span class="kv">${series.length}</span><span class="kd">${NX_VIDEOS.filter(v=>!seriesOf(v)).length} vídeo${NX_VIDEOS.filter(v=>!seriesOf(v)).length===1?' avulso':'s avulsos'}</span></div><div class="k4"><span class="kl">Arquivos adicionais</span><span class="kv">${NX_VIDEOS.reduce((n,v)=>n+v.files.length,0)}</span><span class="kd">vinculados aos vídeos</span></div></section>
 <div class="ct-bar rise" style="--d:2"><label class="sbox">${ic('search',16)}<input id="nxVq" placeholder="Buscar título, descrição ou etiqueta" value="${esc(S.nxVq||'')}" autocomplete="off"></label><div class="chips">${[['todas','Todos'],['serie','Em série'],['avulsa','Avulsos']].map(c=>`<button class="chipf ${filter===c[0]&&!S.nxVSr?'on':''}" data-a="nxVideoFilter" data-v="${c[0]}">${c[1]}</button>`).join('')}<span class="ct-sep"></span>${series.map((s,i)=>`<button class="chipf ct-src ${S.nxVSr===s.id?'on':''}" data-a="nxVideoSeriesFilter" data-v="${s.id}"><i style="background:${HUES[i%HUES.length][1]}"></i>${esc(s.n)}<small>${s.items.length}</small></button>`).join('')}</div></div>
 ${list.length?`<div class="ct-grid rise" style="--d:3">${list.map(v=>`<article class="card ct-pc" data-a="nxVideoOpen" data-v="${v.id}" tabindex="0">${pgThumb({t:v.t,ref:v.tag,sr:seriesOf(v)?.id,yt:v.url,dur:''}).replace('<em> min</em>','')}<div class="ct-pb"><b>${esc(v.t)}</b><span class="ct-who">${esc(seriesOf(v)?.n||'Vídeo avulso')}</span><div class="ct-pm"><span>${v.active?'Ativo':'Inativo'}</span>${v.tag?`<span>${esc(v.tag)}</span>`:''}${v.files.length?`<span>${ic('file',13)}${v.files.length}</span>`:''}</div></div></article>`).join('')}</div>`:'<section class="card mempty rise"><p>Nenhum vídeo aqui.</p><span>Nada corresponde a esse filtro.</span></section>'}`;
}
function nxSeriesList(){
 const q=norm(S.nxSq||''),filter=S.nxSf||'todas',list=NX_SERIES.filter(s=>(filter==='todas'||s.type===filter)&&(!q||norm(s.n+' '+s.desc).includes(q))),tracked=NX_SERIES,progress=s=>s.items.length&&s.people.length?Math.round(s.people.reduce((n,p)=>n+Math.min(100,p.done/s.items.length*100),0)/s.people.length):0,people=tracked.reduce((n,s)=>n+s.people.length,0),done=tracked.reduce((n,s)=>n+s.people.filter(p=>s.items.length&&p.done>=s.items.length).length,0);
 return `<header class="ph rise"><div><p class="eb">Conteúdo</p><h1>Séries</h1><p class="lede">Sequências de pregações, músicas ou vídeos</p></div><div class="pact">${rpBtn('conteudo','series')}<button class="btn pri" data-a="nxSeriesEdit">${ic('plus',15,2.2)}Nova série</button></div></header>
 <section class="card kpis4 rise" style="--d:1"><div class="k4"><span class="kl">Séries</span><span class="kv">${NX_SERIES.length}</span><span class="kd">${NX_SERIES.reduce((n,s)=>n+s.items.length,0)} conteúdos organizados</span></div><div class="k4"><span class="kl">Pessoas inscritas</span><span class="kv">${people}</span><span class="kd">em todas as séries</span></div><div class="k4"><span class="kl">Progresso médio</span><span class="kv">${Math.round(tracked.reduce((n,s)=>n+progress(s),0)/Math.max(1,tracked.length))}<small style="font-size:.55em">%</small></span><span class="kd">nas séries com acompanhamento</span></div><div class="k4"><span class="kl">Conclusões</span><span class="kv" style="color:var(--st-int)">${done}</span><span class="kd">em todas as séries</span></div></section>
 <div class="ct-bar rise" style="--d:2"><label class="sbox">${ic('search',16)}<input id="nxSq" placeholder="Buscar série" value="${esc(S.nxSq||'')}" autocomplete="off"></label><div class="chips">${[['todas','Todas'],['Pregação','Pregações'],['Música','Músicas'],['Vídeo','Vídeos']].map(c=>`<button class="chipf ${filter===c[0]?'on':''}" data-a="nxSeriesFilter" data-v="${c[0]}">${c[1]}<small>${c[0]==='todas'?NX_SERIES.length:NX_SERIES.filter(s=>s.type===c[0]).length}</small></button>`).join('')}</div></div>
 <div class="ct-jg rise" style="--d:3">${list.map((s,i)=>`<article class="card ct-jc" tabindex="0" data-a="nxSeriesOpen" data-v="${s.id}"><div class="ct-jh" style="background:${thumbBg(i%6)}${s.cover?`;background-image:url('${s.cover}');background-size:cover;background-position:center`:''}"><span class="ct-ji">${ic(s.type==='Música'?'music':s.type==='Vídeo'?'play':'book',22)}</span></div><div class="ct-jb"><b>${esc(s.n)}</b><span class="ct-jm">${s.type} · ${s.items.length} conteúdo${s.items.length===1?'':'s'}${nxSerDur(s)}</span><div class="ct-path">${s.items.length?s.items.map(id=>`<i title="${esc(nxCatalog(s.type).find(x=>x.id===id)?.t||'Conteúdo')}"></i>`).join('<em></em>'):'<span class="soft">Nenhum conteúdo ainda</span>'}</div><footer>${`${s.people.length?`<span class="avs">${s.people.slice(0,4).map(p=>avN(p.n)).join('')}</span><span class="ct-jn"><b>${s.people.length}</b> inscritos</span>`:'<span class="soft">Sem inscritos</span>'}${ring(progress(s),52,'var(--brand)')}`}</footer></div></article>`).join('')}<button class="cm-badd" data-a="nxSeriesEdit" style="min-height:300px"><span>${ic('plus',20,2)}</span><b>Nova série</b><small>Uma sequência de conteúdos</small></button></div>`;
}
document.addEventListener('input',e=>{const key={nxVq:'nxVq',nxSq:'nxSq'}[e.target.id];if(!key)return;S[key]=e.target.value;const pos=e.target.selectionStart;render();const input=document.getElementById(key);input.focus();input.setSelectionRange(pos,pos);});

function nxVideoPage(){const v=NX_VIDEOS.find(v=>v.id===S.nxVideo);if(v)return `<nav class="crumb"><button class="lnk" data-a="nxVideoBack">Vídeos</button>${ic('chevR',14)}${esc(v.t)}</nav><header class="ph"><div><h1>${esc(v.t)}</h1><p class="lede">${v.tag?esc(v.tag)+' · ':''}${v.active?'Ativo':'Inativo'}</p></div><div class="pact"><button class="btn sec" data-a="nxVideoEdit" data-v="${v.id}">Editar</button><button class="btn sec" data-a="nxVideoToggle" data-v="${v.id}">${v.active?'Inativar':'Ativar'}</button></div></header><div class="ct-ed"><section class="card ct-ef">${nxThumb(v)}<p>${esc(v.desc)}</p><a class="btn pri" href="${esc(v.url)}" target="_blank" rel="noopener">${ic('play',16)}Abrir vídeo</a></section><aside class="ct-side"><section class="card pc"><h2>Arquivos adicionais</h2>${v.files.map(f=>`<p>${ic('file',15)} ${esc(f)}</p>`).join('')||'<p class="who">Nenhum arquivo.</p>'}<p class="who">Série: ${esc(NX_SERIES.find(s=>s.items.includes(v.id)&&s.type==='Vídeo')?.n||'Avulso')}</p></section></aside></div>`;return nxVideoList();}

document.addEventListener('change',e=>{if(!e.target.matches('.nx-file-pick input'))return;const label=e.target.closest('.nx-file-pick').querySelector('[data-file-label]');if(label)label.textContent=Array.from(e.target.files).map(f=>f.name).join(' · ')||'Escolher arquivo';});
function nxVideoForm(id){const old=NX_VIDEOS.find(v=>v.id===id),v=old||{t:'',desc:'',url:'',tag:'',min:'',files:[]};openDlg(`${dlgHead(old?'Editar vídeo':'Novo vídeo','Link, arquivos e visibilidade')}<form id="nxVideoF" class="fgrid nx-content-form"><label class="fld wide"><span class="fl">Título</span><input name="title" required value="${esc(v.t)}"></label><label class="fld wide"><span class="fl">Resumo</span><textarea name="description" class="ta">${esc(v.desc)}</textarea></label><label class="fld wide"><span class="fl">Link do vídeo</span><input type="url" name="url" required value="${esc(v.url)}" placeholder="https://"></label><label class="fld"><span class="fl">Etiqueta</span><input name="tag" value="${esc(v.tag)}"></label>${nxSerField('Vídeo',id)}${nxFields(v)}<label class="fld wide"><span class="fl">Arquivos adicionais</span><span class="ct-drop nx-file-pick">${ic('upload',18)}<span><b>Escolher arquivos</b><small data-file-label>Slides, esboço ou material complementar</small></span><input type="file" name="files" multiple></span><span class="hint">${v.files.map(esc).join(' · ')}</span></label><div class="dfoot"><button type="button" class="btn sec" data-a="closeDlg">Cancelar</button><button class="btn pri">Salvar vídeo</button></div></form>`,'lg');const f=$('#nxVideoF');nxBindVis(f,v);f.onsubmit=e=>{e.preventDefault();const q=f.elements,url=q.url.value;if(!/^https?:\/\//i.test(url))return toast('Informe um link HTTP ou HTTPS');const obj=old||{id:'vd'+Date.now(),active:true};Object.assign(obj,{t:q.title.value,desc:q.description.value,url,tag:q.tag.value,min:q.nxMin.value,visibility:q.nxVisibility.value,files:[...v.files,...Array.from(q.files.files).map(f=>f.name)]});if(!old)NX_VIDEOS.push(obj);nxApplySeries('Vídeo',obj.id,$$('[name=sr]:checked',f).map(i=>i.value));closeDlg();S.nxVideo=obj.id;render();};}
function nxSeriesPage(){NX_SERIES.filter(s=>s.type==='Pregação').forEach(s=>{s.items=s.items.filter(id=>PREGS.some(p=>p.id===id&&p.sr===s.id));PREGS.filter(p=>p.sr===s.id).forEach(p=>{if(!s.items.includes(p.id))s.items.push(p.id);});});const s=NX_SERIES.find(s=>s.id===S.nxSeries);if(!s)return nxSeriesList();const lib=nxCatalog(s.type);return `<nav class="crumb"><button class="lnk" data-a="nxSeriesBack">Séries</button>${ic('chevR',14)}${esc(s.n)}</nav><header class="ph"><div><h1>${esc(s.n)}</h1><p class="lede">${esc(s.desc)}</p><span>${s.type} · ${s.items.length} itens</span> </div><button class="btn sec" data-a="nxSeriesEdit" data-v="${s.id}">Editar série</button></header><div class="utabs"><button class="${S.nxSeriesTab!=='progress'?'on':''}" data-a="nxSeriesTab" data-v="items">Itens</button>${s.type==='Música'?'':`<button class="${S.nxSeriesTab==='progress'?'on':''}" data-a="nxSeriesTab" data-v="progress">Progresso</button>`}</div><section class="card pc">${S.nxSeriesTab==='progress'&&s.type!=='Música'?s.people.map(p=>{const pct=s.items.length?Math.min(100,Math.round(p.done/s.items.length*100)):0;return `<div class="id-area-row"><b>${esc(p.n)}</b><span class="tr" style="width:160px"><i style="width:${pct}%"></i></span><span>${pct}% · ${pct===100?'Concluiu':'Fazendo'}</span></div>`;}).join('')||'<p class="who">Ninguém começou ainda.</p>':`<div class="sh"><h2>Conteúdos em ordem</h2><button class="btn pri sm" data-a="nxSeriesAdd">${ic('plus',14)}Adicionar item</button></div>${s.items.map((id,i)=>`<div class="id-area-row"><span>${i+1}. <b>${esc(lib.find(x=>x.id===id)?.t||'Conteúdo indisponível')}</b></span><div class="row2"><button class="ibtn sm" data-a="nxSeriesMove" data-v="${i}|-1" ${i===0?'disabled':''} aria-label="Mover para cima">↑</button><button class="ibtn sm" data-a="nxSeriesMove" data-v="${i}|1" ${i===s.items.length-1?'disabled':''} aria-label="Mover para baixo">↓</button><button class="ibtn sm" data-a="nxSeriesRemove" data-v="${i}" aria-label="Remover da série">${ic('x',14)}</button></div></div>`).join('')||'<p class="who">Adicione o primeiro conteúdo.</p>'}`}</section>`;}
