function nxHouseAgenda(){const month=S.calM||'2026-10',meetings=CASAS.filter(c=>c.ppl.some(p=>p.n===ME.n)||c===CASAS[0]).flatMap(c=>c.meets.filter(m=>m.scheduled&&!m.cancelled&&!m.done&&m.d.startsWith(month)&&(!S.calSel||S.calSel===m.d)).map(m=>({c,m})));return `<section class="card pc" style="margin-top:20px"><div class="sh"><h2>Encontros das suas casas</h2><span class="pill">Casa</span></div>${meetings.map(({c,m})=>`<div class="care-meeting"><span class="hd2">${dBRs(m.d)}<small>${m.start}${m.end?'–'+m.end:''}</small></span><span class="grow"><b>${esc(c.n)}</b><p class="who">${m.mode} · ${esc(m.desc)}</p></span>${m.mode==='Remoto'?`<a class="btn sec sm" href="${esc(m.url)}" target="_blank" rel="noopener">Entrar na reunião</a>`:''}<button class="btn sec sm" data-a="nxHouseOpen" data-v="${c.id}|${m.id}">Ver encontro</button></div>`).join('')||'<p class="who">Nenhum encontro agendado neste período.</p>'}</section>`;}
const nxCalPage=calPage;calPage=()=>nxCalPage()+nxHouseAgenda();

